import bpy, bmesh; from mathutils import Vector; from mathutils.bvhtree import BVHTree; from itertools import combinations
dg = bpy.context.evaluated_depsgraph_get()
M = [o for o in bpy.context.scene.objects if o.type == 'MESH' and o.visible_get()]
def wbm(o):
  bm = bmesh.new(); bm.from_object(o, dg); bm.transform(o.matrix_world); return bm
def islands(bm):
  seen = set(); n = 0
  for v in bm.verts:
    if v in seen: continue
    n += 1; st = [v]
    while st:
      x = st.pop()
      if x in seen: continue
      seen.add(x); st += [e.other_vert(x) for e in x.link_edges]
  return n
T = {}
for o in M:
  bm = wbm(o); z = [v.co.z for v in bm.verts]
  print(o.name, [round(d, 3) for d in o.dimensions], 'z', round(min(z), 3), round(max(z), 3), 'scaleOK', all(abs(s - 1) < 1e-4 for s in o.scale), 'nonman', sum(not e.is_manifold for e in bm.edges), 'parts', islands(bm), 'zero', sum(f.calc_area() < 1e-9 for f in bm.faces))
  T[o.name] = BVHTree.FromBMesh(bm); bm.free()
for a, b in combinations(T, 2):
  if T[a].overlap(T[b]) and not (a.startswith('JOINT_') or b.startswith('JOINT_')): print('PENETRATION', a, b)
for o in M:
  bb = [o.matrix_world @ Vector(c) for c in o.bound_box]; zmin = min(v.z for v in bb); c = sum(bb, Vector()) / 8
  hit, loc, *_ = bpy.context.scene.ray_cast(dg, Vector((c.x, c.y, zmin - 1e-4)), Vector((0, 0, -1)))
  gap = zmin - (loc.z if hit else 0.0)
  if gap > 0.002: print('FLOATING', o.name, round(gap, 4))
RULES = {'chair_seat': (0.40, 0.48), 'table_top': (0.71, 0.76), 'desk_top': (0.70, 0.76), 'counter_top': (0.85, 0.92)}
for o in M:
  for k, (lo, hi) in RULES.items():
    if o.name.startswith(k):
      top = max((o.matrix_world @ Vector(c)).z for c in o.bound_box)
      if not lo <= top <= hi: print('RULE', o.name, round(top, 3), (lo, hi))
